using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities to the research agent.
/// In production, replace the simulated search with a real search API (e.g., Bing Search).
/// </summary>
public sealed class WebSearchService
{
    private static readonly HttpClient s_httpClient = new();

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return")] int maxResults = 5)
    {
        // Simulated search results for demonstration.
        // Replace with a real search API (Bing Search API, Google Custom Search, etc.)
        await Task.Delay(100); // Simulate network latency

        var results = new[]
        {
            new { Title = $"Overview of {query}", Snippet = $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future directions.", Url = $"https://example.com/overview-{Uri.EscapeDataString(query)}" },
            new { Title = $"Latest research on {query}", Snippet = $"Recent studies and publications about {query} reveal new findings and developments in the field.", Url = $"https://example.com/research-{Uri.EscapeDataString(query)}" },
            new { Title = $"{query} - Key challenges and opportunities", Snippet = $"An analysis of the main challenges facing {query} today, along with emerging opportunities for growth.", Url = $"https://example.com/challenges-{Uri.EscapeDataString(query)}" },
            new { Title = $"Expert opinions on {query}", Snippet = $"Leading experts share their perspectives on the current state and future of {query}.", Url = $"https://example.com/experts-{Uri.EscapeDataString(query)}" },
            new { Title = $"Practical applications of {query}", Snippet = $"Real-world use cases and applications demonstrating the impact of {query} across industries.", Url = $"https://example.com/applications-{Uri.EscapeDataString(query)}" },
        };

        var limited = results.Take(maxResults);
        return string.Join("\n\n", limited.Select((r, i) =>
            $"[{i + 1}] {r.Title}\n    {r.Snippet}\n    Source: {r.Url}"));
    }
}

using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// </summary>
public sealed class NoteService
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a title and content. Use this to record important findings from your research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content of the note")] string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}\n[Saved at {n.Timestamp:u}]"));
    }

    [Description("Search notes for a keyword and return matching notes.")]
    public string SearchNotes(
        [Description("The keyword to search for in note titles and content")] string keyword)
    {
        var matches = _notes
            .Where(n => n.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase)
                     || n.Content.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
        {
            return $"No notes found matching \"{keyword}\".";
        }

        return string.Join("\n\n", matches.Select((n, i) =>
            $"--- Match {i + 1}: {n.Title} ---\n{n.Content}"));
    }

    private sealed record Note(string Title, string Content, DateTime Timestamp);
}

