arguments.new_str:
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

namespace ResearchAgent;

/// <summary>
/// Hosted service that runs the research agent loop, accepting topics from the user
/// and using the agent to search, take notes, and produce a summary.
/// </summary>
public sealed class ResearchHostedService(
    IChatClient chatClient,
    NoteService noteService,
    WebSearchService webSearchService,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════════╗");
        Console.WriteLine("║        AI Research Agent                 ║");
        Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
        Console.WriteLine("╚══════════════════════════════════════════╝");
        Console.WriteLine();

        while (!stoppingToken.IsCancellationRequested)
        {
            Console.Write("Research topic: ");
            var topic = Console.ReadLine();

            if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
            {
                break;
            }

            await ResearchTopicAsync(topic, stoppingToken);
            Console.WriteLine();
        }

        lifetime.StopApplication();
    }

    private async Task ResearchTopicAsync(string topic, CancellationToken cancellationToken)
    {
        Console.WriteLine($"\n🔍 Researching: {topic}\n");

        var tools = new AITool[]
        {
            AIFunctionFactory.Create(webSearchService.SearchWebAsync),
            AIFunctionFactory.Create(noteService.SaveNote),
            AIFunctionFactory.Create(noteService.GetAllNotes),
            AIFunctionFactory.Create(noteService.SearchNotes),
        };

        var agent = new ChatClientAgent(
            chatClient,
            new ChatClientAgentOptions
            {
                Name = "ResearchAgent",
                Description = "An AI agent that researches topics by searching the web and taking notes.",
                ChatOptions = new ChatOptions
                {
                    Temperature = 0f,
                    MaxOutputTokens = 2048,
                    Tools = [.. tools],
                },
            });

        var session = await agent.CreateSessionAsync(cancellationToken);

        var systemMessage = new ChatMessage(ChatRole.System, """
            You are a research agent. Your task is to thoroughly research a given topic by:
            1. Searching the web for relevant information using different query angles
            2. Taking notes on key findings as you discover them
            3. Producing a well-structured summary at the end

            Process:
            - Start by searching for the topic broadly
            - Then search for specific aspects (challenges, applications, recent developments)
            - Save important findings as notes with descriptive titles
            - After gathering enough information, retrieve all your notes and synthesize a final summary

            Always provide your final summary with clear sections and cite your sources.
            """);

        var userMessage = new ChatMessage(ChatRole.User,
            $"Please research the following topic and provide a comprehensive summary: {topic}");

        try
        {
            var runOptions = new ChatClientAgentRunOptions
            {
                ChatOptions = new ChatOptions
                {
                    Temperature = 0f,
                    MaxOutputTokens = 2048,
                    Tools = [.. tools],
                },
            };

            await foreach (var update in agent.RunStreamingAsync(
                [systemMessage, userMessage], session, runOptions, cancellationToken))
            {
                if (!string.IsNullOrEmpty(update.Text))
                {
                    Console.Write(update.Text);
                }

                logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                    update.Role, update.Text?.Length ?? 0);
            }

            Console.WriteLine();
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine("\n⚠️  Research cancelled.");
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Error during research");
            Console.WriteLine($"\n❌ Error: {ex.Message}");
        }
    }
}

